import{_ as t,o as s,c as a,ag as i}from"./chunks/framework.2cFhd8Ux.js";const m=JSON.parse('{"title":"Week 2 — Lab and Assignment","description":"","frontmatter":{"source":"weeks/02-inside-agents/lab.md"},"headers":[],"relativePath":"weeks/02-inside-agents/lab.md","filePath":"weeks/02-inside-agents/lab.md"}'),n={name:"weeks/02-inside-agents/lab.md"};function o(r,e,h,d,l,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="week-2--lab-and-assignment" tabindex="-1">Week 2 — Lab and Assignment <a class="header-anchor" href="#week-2--lab-and-assignment" aria-label="Permalink to &quot;Week 2 — Lab and Assignment&quot;">​</a></h1><blockquote><p>Your first contact with the class codebase is comprehension, not change. Build it, test it, let an agent map it, and find out how much of the map is true.</p></blockquote><p><strong>AI-use key:</strong> 🟢 AI on: use an agent to explore, following the <a href="./../../resources/safe-loop.html">Safe Loop</a> · 🔴 AI off: you open the files and run the checks yourself. A second agent confirming the first is still an inferred claim.</p><p><strong>Rules for agents this week</strong> (<a href="./../../setup/safety-contract.html">safety contract</a>): the class codebase is code you didn&#39;t write, so it runs only in a sandbox (<a href="./../../setup/safety-contract.html#3-untrusted-code-runs-in-a-sandbox">rule 3</a>). Its codespace gets one secret, your free-tier key, and nothing else (<a href="./../../setup/safety-contract.html#4-no-real-secrets-near-an-agent">rule 4</a>). That is acceptable only because this session reads the pinned class code and nothing else: no issues, no web pages, no other teams&#39; code. Approvals stay on. The agent reads; it doesn&#39;t edit, except to save its own map if you approve that one write.</p><h2 id="before-the-lab-20-min" tabindex="-1">Before the Lab (20 min) <a class="header-anchor" href="#before-the-lab-20-min" aria-label="Permalink to &quot;Before the Lab (20 min)&quot;">​</a></h2><ol><li><strong>Read</strong> <a href="./../../project/class-codebase.html">the class codebase</a>: the project, the class fork, the pinned commit, the language and the test command. Below, <code>[install command]</code> and <code>[test command]</code> mean the ones recorded there.</li><li><strong>Fork the class fork</strong> to your own account (<strong>Fork</strong> on the class fork&#39;s page). Your onboarding report goes in this fork; team work goes in your team fork later.</li><li><strong>Read the dev container config before you build it.</strong> On github.com, open <code>.devcontainer/devcontainer.json</code> in your fork, if there is one, and read any <code>postCreateCommand</code>, features or Dockerfile it names: they run when the codespace is created (<a href="./../../setup/sandboxes.html#running-an-agent-on-untrusted-code-step-by-step">sandboxes</a>).</li><li><strong>Give the codespace your key, and only your key.</strong> github.com → <strong>Settings</strong> → <strong>Codespaces</strong>: add your fork to the repository access of the secret your agent reads (for Gemini CLI, a secret named <code>GEMINI_API_KEY</code> holding your free AI Studio key). Check that no other secret lists this fork.</li><li><strong>Create a codespace</strong> on your fork (2-core), let it finish building, then stop it until the Lab.</li></ol><h2 id="lab--onboard-to-the-class-codebase-75-min" tabindex="-1">Lab — Onboard to the class codebase (75 min) <a class="header-anchor" href="#lab--onboard-to-the-class-codebase-75-min" aria-label="Permalink to &quot;Lab — Onboard to the class codebase (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Part</th><th>Core or If time</th></tr></thead><tbody><tr><td>0:00–0:05</td><td>Setup check</td><td>—</td></tr><tr><td>0:05–0:20</td><td><a href="#part-1--build-it-from-the-readme-15-min">Part 1 — Build it from the README</a></td><td>Core</td></tr><tr><td>0:20–0:30</td><td><a href="#part-2--run-the-tests-10-min">Part 2 — Run the tests</a></td><td>Core</td></tr><tr><td>0:30–0:45</td><td><a href="#part-3--read-the-agent-files-then-map-15-min">Part 3 — Read the agent files, then map</a></td><td>Core</td></tr><tr><td>0:45–0:55</td><td><a href="#part-4--verify-the-map-10-min-continue-at-home">Part 4 — Verify the map</a> (🔴 AI off)</td><td>Core</td></tr><tr><td>—</td><td><a href="#part-5--find-mini-agents-parts-if-time">Part 5 — Find mini-agent&#39;s parts</a> · <a href="#part-6--hotspots-from-history-if-time">Part 6 — Hotspots from history</a></td><td>If time</td></tr><tr><td>0:55–1:10</td><td><a href="#checkoff-15-min">Checkoff</a></td><td>—</td></tr><tr><td>1:10–1:15</td><td><a href="#next-steps-5-min">Next steps</a></td><td>—</td></tr></tbody></table><h3 id="setup-check-5-min" tabindex="-1">Setup check (5 min) <a class="header-anchor" href="#setup-check-5-min" aria-label="Permalink to &quot;Setup check (5 min)&quot;">​</a></h3><p>Start your codespace. In its terminal, check that you&#39;re on the pinned commit, and that your key arrived without printing it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rev-parse</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --short</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HEAD</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$GEMINI_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;key is set&quot;</span></span></code></pre></div><p>The hash must match the pinned commit in <a href="./../../project/class-codebase.html">the class codebase</a>. Create the report file now, from the outline in the <a href="#the-report">assignment</a>, and keep notes in it as you go:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> course</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">touch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> course/ONBOARDING.md</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> course/AI_LOG.md</span></span></code></pre></div><h3 id="part-1--build-it-from-the-readme-15-min" tabindex="-1">Part 1 — Build it from the README (15 min) <a class="header-anchor" href="#part-1--build-it-from-the-readme-15-min" aria-label="Permalink to &quot;Part 1 — Build it from the README (15 min)&quot;">​</a></h3><p><strong>Core · 🟢 AI on</strong> (but follow the README, not an agent)</p><p>Follow the project&#39;s README (or <code>CONTRIBUTING.md</code>) development setup <strong>exactly as written</strong>, in order. Time each step:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [install command]</span></span></code></pre></div><p>In <code>course/ONBOARDING.md</code>, under &quot;Build&quot;, record each command, how long it took, and every place where the README was wrong, out of date or silent: a missing prerequisite, a renamed script, a step only CI performs. Each of those is an <strong>observed</strong> finding and goes in your report.</p><p>Don&#39;t let an agent &quot;fix&quot; the build by editing lockfiles, CI configuration or dependency versions (<a href="./../../resources/troubleshooting.html#the-class-codebase-wont-build">troubleshooting</a>). If a step fails, record the exact error, check <a href="./../../project/class-codebase.html">the class codebase</a> for staff notes, and ask your neighbors.</p><p>✅ <strong>Checkpoint:</strong> the project builds (or you have the exact error and what you tried), and every command is in your notes.</p><h3 id="part-2--run-the-tests-10-min" tabindex="-1">Part 2 — Run the tests (10 min) <a class="header-anchor" href="#part-2--run-the-tests-10-min" aria-label="Permalink to &quot;Part 2 — Run the tests (10 min)&quot;">​</a></h3><p><strong>Core · 🟢 AI on</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [test command]</span></span></code></pre></div><p>Record the counts (passed, failed, skipped), the run time and the machine size. If anything fails on the pinned commit, say whether you think it&#39;s the environment or the code, and tag that inferred until you&#39;ve checked.</p><p>Then find out how to run <strong>one</strong> test file and <strong>one</strong> test by name. You&#39;ll need that to verify claims in Part 4. For pytest it&#39;s <code>pytest [path]::[test name]</code> or <code>-k [pattern]</code>; JavaScript and TypeScript runners take a file path and usually a name filter (check the runner&#39;s <code>--help</code>). Run one and record the command.</p><p>✅ <strong>Checkpoint:</strong> the full-suite command, its counts and time, and a working single-test command, all in your notes.</p><h3 id="part-3--read-the-agent-files-then-map-15-min" tabindex="-1">Part 3 — Read the agent files, then map (15 min) <a class="header-anchor" href="#part-3--read-the-agent-files-then-map-15-min" aria-label="Permalink to &quot;Part 3 — Read the agent files, then map (15 min)&quot;">​</a></h3><p><strong>Core · 🟢 AI on</strong></p><p><strong>First, read what a stranger wrote for your agent.</strong> Project instruction files and agent configs are instructions to whatever agent opens the repository (<a href="./../../setup/sandboxes.html#running-an-agent-on-untrusted-code-step-by-step">sandboxes, step 4</a>). List them and read each one before your agent does:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls-files</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -iE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;(^|/)(agents|claude|gemini)\\.md$|copilot-instructions|\\.cursorrules|(^|/)\\.(cursor|gemini|claude|vscode)/|(^|/)\\.?mcp\\.json$|(^|/)opencode\\.jsonc?$&#39;</span></span></code></pre></div><p>Note anything that tells an agent to run a command, fetch a URL or change its settings, and any MCP server it would start. The list isn&#39;t complete (every harness has its own file names), so also skim the README for agent setup. The class codebase is itself an agent, so its source also contains prompts written for a model. Your agent will read them as files. Watch whether it treats them as data, or starts following them.</p><p><strong>Then map it.</strong> Start your CLI agent in the repository root (<a href="./../../TOOLS.html#tools-by-week">Tool Handout: Tools by week</a>: Gemini CLI, or the fallback), in its default approval mode. If its settings let you switch off web fetch and web search for this session, do; otherwise deny those calls. Give it this prompt:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I am onboarding to this repository. Read only: do not edit files, and do not run commands that change anything.</span></span>
<span class="line"><span>Produce an architecture map as a Markdown table with columns: # | Claim | Evidence (file:line, or the command you ran) | Confidence.</span></span>
<span class="line"><span>Cover:</span></span>
<span class="line"><span>1. The entry points a user runs.</span></span>
<span class="line"><span>2. The path from a user&#39;s request to the model call and back, as a numbered list of functions with file:line.</span></span>
<span class="line"><span>3. Where tools are defined, and how one tool is registered.</span></span>
<span class="line"><span>4. Where permission or approval checks happen, and what they check.</span></span>
<span class="line"><span>5. How model providers, base URLs and API keys are configured.</span></span>
<span class="line"><span>6. Where the system prompt is assembled, and what goes into it.</span></span>
<span class="line"><span>7. How the conversation is truncated or summarized when it grows.</span></span>
<span class="line"><span>8. How the tests are organized, and the command that runs one test file.</span></span>
<span class="line"><span>For every claim, cite the exact file and line you read. If you did not open the file, write &quot;not opened&quot; in the Evidence column. Aim for 20 to 30 claims.</span></span></code></pre></div><p>Save the answer verbatim as <code>course/architecture-map.agent.md</code>. Copy it from the terminal, or approve one write to exactly that file. This file is the agent&#39;s work, unedited. Your corrections go in the report.</p><p>✅ <strong>Checkpoint:</strong> the agent&#39;s map is saved, and you&#39;ve noted which instruction files exist and anything in them that surprised you.</p><h3 id="part-4--verify-the-map-10-min-continue-at-home" tabindex="-1">Part 4 — Verify the map (10 min, continue at home) <a class="header-anchor" href="#part-4--verify-the-map-10-min-continue-at-home" aria-label="Permalink to &quot;Part 4 — Verify the map (10 min, continue at home)&quot;">​</a></h3><p><strong>Core · 🔴 AI off</strong></p><p>A citation is a lead, not evidence, until you open it. In <code>course/ONBOARDING.md</code>, start a claims table:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| # | Claim (from the map, or your own) | Evidence: file:line at [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">commit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], or command → output | How checked | Tag | Status |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|---|---|---|---|---|---|</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 4 | Approval checks happen in [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">function</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`[file]:[line]\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> at </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`a1b2c3d\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> | read; broke it | observed | confirmed |</span></span></code></pre></div><p>Status is one of <strong>confirmed</strong>, <strong>wrong</strong>, <strong>partly right</strong> (say which part) or <strong>unsupported</strong> (the cited line doesn&#39;t show it). Check claims three ways, strongest last:</p><ol><li><p><strong>Read it.</strong> Open the cited lines, and search for what they name:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;[start],[end]p&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [file]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[function or symbol]&quot;</span></span></code></pre></div></li><li><p><strong>Run it.</strong> Run the narrowest test that exercises the claim, with the single-test command from Part 2.</p></li><li><p><strong>Break it on purpose.</strong> Change one line in the code the claim is about (flip a condition, return early), run the test you think covers it, and see it fail. Then undo:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [file]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --short</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;:!course&#39;</span></span></code></pre></div><p>The status command (which ignores your <code>course/</code> notes) must print nothing before you go on. If no test fails, you&#39;ve found something else worth reporting: that code is untested.</p></li></ol><p>✅ <strong>Checkpoint:</strong> at least five claims checked, each with located evidence, a tag and a status, and at least one checked by breaking it.</p><h3 id="part-5--find-mini-agents-parts-if-time" tabindex="-1">Part 5 — Find mini-agent&#39;s parts (If time) <a class="header-anchor" href="#part-5--find-mini-agents-parts-if-time" aria-label="Permalink to &quot;Part 5 — Find mini-agent&#39;s parts (If time)&quot;">​</a></h3><p><strong>If time · 🟢 AI on to search, 🔴 AI off to confirm</strong></p><p>For each part of <code>mini-agent</code> you read in week 1, find its counterpart here, with file and line: the loop (<code>runAgent</code>), tool schemas (<code>TOOL_DEFINITIONS</code>), executing a tool call (<code>executeToolCall</code>), the approval gate (<code>createApprovalGate</code>), the system prompt (<code>SYSTEM_PROMPT</code>), the model client with retries (<code>callModel</code>), and the trace. Then list what this harness has that <code>mini-agent</code> doesn&#39;t: compaction, subagents, permission modes, a sandbox, session storage. This table goes into your report.</p><h3 id="part-6--hotspots-from-history-if-time" tabindex="-1">Part 6 — Hotspots from history (If time) <a class="header-anchor" href="#part-6--hotspots-from-history-if-time" aria-label="Permalink to &quot;Part 6 — Hotspots from history (If time)&quot;">​</a></h3><p><strong>If time · 🟢 AI on</strong></p><p>If the class fork kept upstream history, the files that change most often are where bugs and merge conflicts concentrate:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;12 months ago&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name-only</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;^$&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uniq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rn</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -20</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [file] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -20</span></span></code></pre></div><p>Compare the top of the list with the files the tests exercise. A file that changes often and has few tests is a candidate risky area for your report.</p><h3 id="checkoff-15-min" tabindex="-1">Checkoff (15 min) <a class="header-anchor" href="#checkoff-15-min" aria-label="Permalink to &quot;Checkoff (15 min)&quot;">​</a></h3><p>Show a staff member, in your codespace, with your notes pushed to your fork:</p><ol><li><code>git rev-parse --short HEAD</code> matching the pinned commit, and your build notes: the commands, their times and the README&#39;s gaps.</li><li>The test run: the command, counts and time, plus a single-test command that works.</li><li><code>course/architecture-map.agent.md</code>, saved verbatim.</li><li>At least five claims in <code>course/ONBOARDING.md</code> with evidence, a tag and a status, one of them checked by breaking code, with the source restored afterward.</li><li>On request, one claim shown live: open the file at the line and explain it.</li></ol><p>Scored with the <a href="./../../assessment/rubrics.html#lab-checkoff-5-points">Lab checkoff rubric</a>. A build that fails for a reason you&#39;ve recorded exactly still earns partial credit.</p><h3 id="next-steps-5-min" tabindex="-1">Next steps (5 min) <a class="header-anchor" href="#next-steps-5-min" aria-label="Permalink to &quot;Next steps (5 min)&quot;">​</a></h3><ul><li>Push (<code>git add course &amp;&amp; git commit &amp;&amp; git push</code>) and stop the codespace.</li><li>Find your team (announced in the Seminar) and book a 45-minute charter meeting this week.</li><li>CS [5xxx]: check the presentation schedule when it&#39;s posted.</li></ul><h2 id="assignment--the-onboarding-report" tabindex="-1">Assignment — The onboarding report <a class="header-anchor" href="#assignment--the-onboarding-report" aria-label="Permalink to &quot;Assignment — The onboarding report&quot;">​</a></h2><p>About 4 hours, individual. Everything goes in the <code>course/</code> folder of <strong>your fork</strong> of the class fork. Submit the fork&#39;s URL and the commit to grade on Canvas (<a href="./../../assessment/#how-to-submit">how to submit</a>). Your team&#39;s M0 proposal in week 5 builds on the four reports, so write for a teammate who hasn&#39;t opened the code yet.</p><h3 id="deliverables" tabindex="-1">Deliverables <a class="header-anchor" href="#deliverables" aria-label="Permalink to &quot;Deliverables&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Deliverable</th><th>AI use</th></tr></thead><tbody><tr><td><code>course/ONBOARDING.md</code>, the report (about 1,500 words plus tables)</td><td>🟢 AI on to explore; 🔴 AI off for sections 5 and 6 and for every tag</td></tr><tr><td><code>course/architecture-map.agent.md</code>, the agent&#39;s map, unedited</td><td>🟢 AI on</td></tr><tr><td><code>course/AI_LOG.md</code> (<a href="./../../templates/AI_LOG.html">template</a>) with your mapping sessions, and <code>Assisted-by:</code> trailers</td><td>🟢 AI on</td></tr><tr><td><strong>Team:</strong> <code>course/TEAM_CHARTER.md</code> in your team fork</td><td>🟢 AI on, but it&#39;s an agreement among people: write it together</td></tr></tbody></table><h3 id="the-report" tabindex="-1">The report <a class="header-anchor" href="#the-report" aria-label="Permalink to &quot;The report&quot;">​</a></h3><p><code>course/ONBOARDING.md</code> has these sections:</p><ol><li><strong>Summary.</strong> What the project does, in three sentences. The pinned commit, the agent and model you used, and the date.</li><li><strong>Build and test.</strong> The exact commands, their times and the machine size; every README gap you found; the test counts, any failures on the pinned commit, and the single-test command. Tag each claim.</li><li><strong>Architecture map.</strong> The main components with their paths (a table, or a Mermaid diagram). The request path traced end to end as a numbered list of functions with <code>file:line</code>: user input → loop → model call → tool call → permission check → tool runs → result back to the model → output. Then <strong>compared with <code>mini-agent</code></strong>: for each part of <code>mini-agent</code> (Part 5&#39;s list), where it lives here and what this harness adds. Every line tagged.</li><li><strong>Three risky areas.</strong> For each: where it is; why it&#39;s risky, with evidence (it enforces permissions or handles keys; it changes often; few tests touch it; it&#39;s large or deeply nested); what could go wrong if an agent changed it; and what you&#39;d require before merging a change there (characterization tests, a second reviewer, a security check).</li><li><strong>Five verified claims</strong> (🔴 AI off). Each with its evidence (<code>file:line</code> at the pinned commit, or a command and its output) and how you checked it. At least one checked by breaking code on purpose, showing the failing test&#39;s name and output.</li><li><strong>Two claims the agent got wrong</strong> (🔴 AI off). For each: what the map said (quote it), what is actually true (observed, with evidence), how you found out, and why you think it went wrong (tagged inferred: a stale file, a name that sounded right, a summary of a file it didn&#39;t open). If you check 20 claims and find fewer than two wrong, report that, with the count. That&#39;s a finding too.</li><li><strong>Open questions.</strong> Inferred claims you didn&#39;t check, and how you would check each.</li></ol><p><strong>Your AI log entry</strong> records the mapping session: the agent and model, the prompt (in a <code>text</code> block), what you delegated (the map), what you kept (the verification) and what the checks caught.</p><h3 id="the-team-charter-team-deliverable" tabindex="-1">The team charter (team deliverable) <a class="header-anchor" href="#the-team-charter-team-deliverable" aria-label="Permalink to &quot;The team charter (team deliverable)&quot;">​</a></h3><p>Meet as a team (45 minutes), fill in <a href="./../../templates/TEAM_CHARTER.html">TEAM_CHARTER.md template</a> as <code>course/TEAM_CHARTER.md</code> in your team fork, and have <strong>each member</strong> add their own sign-off line in their own commit. Include the &quot;free allowances&quot; plan, so the team doesn&#39;t run one pool dry in the same week (<a href="./../../TOOLS.html#spreading-the-work-across-free-allowances">Tool Handout: Spreading the work across free allowances</a>). The charter is due with this assignment and checked at M0, in the &quot;Team setup&quot; row of the <a href="./../../assessment/rubrics.html#m0-proposal">M0 rubric</a>. It isn&#39;t part of this week&#39;s 15 points.</p><h3 id="how-its-graded" tabindex="-1">How it&#39;s graded <a class="header-anchor" href="#how-its-graded" aria-label="Permalink to &quot;How it&#39;s graded&quot;">​</a></h3><p>20 points for the week: the Lab checkoff (5) and the report (15), on the <a href="./../../assessment/rubrics.html#labs-and-assignments">labs and assignments rubric</a>. This week, the rows mean:</p><table tabindex="0"><thead><tr><th>Row (points)</th><th>What it means this week</th></tr></thead><tbody><tr><td><strong>Deliverables work</strong> (5)</td><td>A teammate could build and test the project from section 2 alone; the map covers the request path, tools, permissions, providers, the system prompt and context management; three risky areas, five verified claims and two wrong ones (or the documented count) are present</td></tr><tr><td><strong>Verification</strong> (4)</td><td>Every claim tagged; every verified claim located at the pinned commit; at least one checked by breaking code, with the failing test shown; each wrong claim set against what&#39;s actually true, with evidence</td></tr><tr><td><strong>Process record</strong> (3)</td><td><code>AI_LOG.md</code> with the mapping session, the prompt, and what verification caught; the agent&#39;s map kept unedited; commits with <code>Assisted-by:</code> trailers where AI helped</td></tr><tr><td><strong>Write-up</strong> (3)</td><td>Risky areas argued from evidence, not impressions; the <code>mini-agent</code> comparison specific; open questions and limitations stated</td></tr></tbody></table><p><strong>Due before next week&#39;s Seminar (default 11:59 pm the night before).</strong> The week 3 Seminar opens with a 7-minute, 🔴 AI-off quiz on your report: expect &quot;where does [part] live, and how do you know?&quot;</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Minimum to keep up.</strong> The class codebase builds in your codespace, you can run one test by name, and you can show from the code (observed) where its loop, its tools and its permission checks live. Week 3&#39;s <code>AGENTS.md</code> for this codebase and every team milestone depend on it. If the build is blocked, record the exact error and what you tried, and complete the map and verification by reading: a precise blocker earns partial credit.</p></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Fix</th></tr></thead><tbody><tr><td>GitHub won&#39;t create your fork (&quot;you already have a fork&quot;)</td><td>GitHub allows one fork per repository network per account. Use your existing fork: <code>git remote add class https://github.com/[course-org]/[project].git</code>, <code>git fetch class</code>, then <code>git switch -c onboarding [pinned commit]</code>, and submit that branch</td></tr><tr><td>The build runs out of memory or takes forever on 2 cores</td><td>Use a 4-core machine for the build only, then switch back: it spends hours twice as fast (<a href="./../../resources/troubleshooting.html#the-class-codebase-wont-build">troubleshooting</a>)</td></tr><tr><td><code>key is set</code> doesn&#39;t print</td><td>The secret doesn&#39;t list this fork, or was added after the codespace was created: fix the access, then reload or rebuild</td></tr><tr><td>The agent hits rate limits or &quot;request too large&quot;</td><td>It&#39;s reading too much at once. Ask one question of the prompt at a time, in fresh sessions (<a href="./../../resources/troubleshooting.html#request-too-large-or-the-context-is-full">troubleshooting</a>)</td></tr><tr><td>The map has no citations, or cites lines that don&#39;t exist</td><td>Keep it as saved: nonexistent citations are wrong claims for section 6. Then rerun the prompt on one area, insisting on &quot;not opened&quot;</td></tr><tr><td>The agent starts following instructions from a prompt file it read</td><td>Stop the session, record the step (it&#39;s an injection example for week 4) and start a fresh one</td></tr><tr><td>Code you broke on purpose stays broken</td><td><code>git restore [file]</code>, then <code>git status --short -- . &#39;:!course&#39;</code> and the test command again</td></tr></tbody></table>`,73)])])}const u=t(n,[["render",o]]);export{m as __pageData,u as default};
